const salesText = fs.readFileSync(salesPath, 'utf8');
const rows = parseCsv(salesText);
const { summary, issues } = computeMonthly(rows);
if (issues.length > 0) {
  console.error('Data issues found and excluded:');
  for (const issue of issues) console.error(`- ${issue}`);
}
const output = toCsv(summary);

if (fs.existsSync(summaryPath)) {
  const existing = fs.readFileSync(summaryPath, 'utf8').replace(/\r\n/g, '\n');
  assertSame(output, existing);
  console.log(`OK: ${summaryPath} matches independent calculation from ${salesPath}.`);

